function hydrateForms(r,res){const hs=[...r.querySelectorAll('h3')];const create=hs.find(h=>h.textContent.startsWith('Create ')),edit=hs.find(h=>h.textContent.startsWith('Edit '));if(create)create.textContent='Create '+res.singular;if(edit)edit.textContent='Edit '+res.singular;const cards=[create?.closest('.rounded-lg.border'),edit?.closest('.rounded-lg.border')];cards.forEach((c,i)=>{if(!c)return;const badges=c.querySelectorAll('span.inline-flex');if(badges[0])badges[0].textContent=res.fields.length+' fields';if(badges[1])badges[1].textContent=res.fields.filter(f=>f.required).length+' required';const mono=c.querySelector('.font-mono');if(mono)mono.textContent=i===0?res.routeBase+'/create':res.routeBase+'/[id]/edit'})}
function hydrateDetails(r,res){const h=[...r.querySelectorAll('h3')].find(x=>x.textContent.includes('details composition'));if(h)h.textContent=res.singular+' details composition';const card=h?.closest('.rounded-lg.border'),content=card?.querySelector('.px-5.pb-5');if(content){content.innerHTML='';res.fields.forEach(f=>{const d=document.createElement('div');if(f.type==='textarea')d.className='sm:col-span-2';d.innerHTML='<p class="text-xs font-semibold uppercase tracking-wider text-muted-foreground"></p><p class="mt-1 text-sm font-medium"></p>';d.children[0].textContent=f.label;d.children[1].textContent=sampleValue(f);content.append(d)})}const routeCard=[...r.querySelectorAll('h3')].find(x=>x.textContent==='Route contract')?.closest('.rounded-lg.border');const mono=routeCard?.querySelector('.font-mono');if(mono)mono.textContent=res.routeBase+'/[id]';const actionCard=[...r.querySelectorAll('h3')].find(x=>x.textContent==='Enabled actions')?.closest('.rounded-lg.border'),wrap=actionCard?.querySelector('.flex.flex-wrap');if(wrap){const template=wrap.querySelector('span');wrap.innerHTML='';res.actions.forEach(a=>{const s=template?.cloneNode(true)||document.createElement('span');s.textContent=a;wrap.append(s)})}}
function hydratePreview(r,res){const h=[...r.querySelectorAll('h3')].find(x=>x.textContent.includes('module preview'));if(h)h.textContent=res.plural+' module preview';const list=r.querySelector('[data-tab-panel="list"]');const search=list?.querySelector('input');if(search)search.placeholder='Search '+res.plural.toLowerCase()+'...';const header=list?.querySelector('.grid.grid-cols-4.border-b');const row=list?.querySelector('.grid.grid-cols-4.items-center');const vis=res.fields.filter(f=>f.listVisible).slice(0,3);if(header){const spans=header.querySelectorAll('span');vis.forEach((f,i)=>{if(spans[i])spans[i].textContent=f.label})}if(row){const spans=row.querySelectorAll('span');vis.forEach((f,i)=>{if(spans[i])spans[i].textContent='Sample '+f.label.toLowerCase()})}const form=r.querySelector('[data-tab-panel="form"]');const p=form?.querySelector('p.font-semibold');if(p)p.textContent='Create '+res.singular;const grid=form?.querySelector('.grid');if(grid){grid.innerHTML='';res.fields.slice(0,6).forEach(f=>{const d=document.createElement('div');if(f.type==='textarea')d.className='sm:col-span-2';d.innerHTML='<p class="mb-2 text-sm font-medium"></p><div class="h-10 rounded-md border border-input bg-background px-3 py-2 text-sm text-muted-foreground"></div>';d.children[0].textContent=f.label+(f.required?' *':'');d.children[1].textContent=f.placeholder||'Enter '+f.label.toLowerCase();grid.append(d)})}const det=r.querySelector('[data-tab-panel="details"]');if(det){const grid=det.querySelector('.grid');if(grid){grid.innerHTML='';res.fields.forEach(f=>{const d=document.createElement('div');d.innerHTML='<p class="text-xs font-semibold uppercase tracking-wider text-muted-foreground"></p><p class="mt-1 text-sm font-medium">Sample value</p>';d.children[0].textContent=f.label;if(f.required){const s=document.createElement('span');s.className='inline-flex shrink-0 items-center justify-center gap-1 whitespace-nowrap rounded-full px-2.5 py-1 text-xs font-medium leading-4 bg-secondary text-secondary-foreground mt-2';s.textContent='Required';d.append(s)}grid.append(d)})}}}
function initCodeExport(r,res){const files=buildCrudCode(res),tabs=r.querySelector('[data-tabs]');Object.entries(files).forEach(([name,code])=>{const panel=r.querySelector(`[data-tab-panel="${CSS.escape(name)}"]`);const pre=panel?.querySelector('code');if(pre)pre.textContent=code;const b=panel?.querySelector('button');if(b&&!b.dataset.d2Crud){b.dataset.d2Crud='true';b.addEventListener('click',async()=>{let ok=false;try{await navigator.clipboard.writeText(code);ok=true}catch{}b.textContent=ok?'Copied':'Copy';r.dataset.d2CrudCopied=name;setTimeout(()=>{if(document.contains(b))b.textContent='Copy'},1500)})}})}
function initCrud(r){const res=readResource();const rt=route();if(rt==='/developer/crud-generator')initCrudOverview(r,res);else if(rt.endsWith('/resource'))initResource(r,res);else if(rt.endsWith('/fields'))renderFields(r);else if(rt.endsWith('/table'))initTable(r);else if(rt.endsWith('/actions'))initActions(r);else if(rt.endsWith('/data-api'))initDataApi(r);else if(rt.endsWith('/templates'))initTemplates(r);else if(rt.endsWith('/import-schema'))initSchema(r);else if(rt.endsWith('/ai-assistant'))initAi(r);else if(rt.endsWith('/forms'))hydrateForms(r,res);else if(rt.endsWith('/details'))hydrateDetails(r,res);else if(rt.endsWith('/preview'))hydratePreview(r,res);else if(rt.endsWith('/code-export'))initCodeExport(r,res)}
export function initD2DeveloperInteractions(){const rt=route();if(!DEV_ROUTES.has(rt))return;const r=root();if(!r)return;if(rt==='/developer/api-keys')initApiKeys(r);else if(rt==='/developer/api-playground')initPlayground(r);else if(rt==='/developer/endpoints')initDeveloperFilters(r,'endpoints');else if(rt==='/developer/platform')initDeveloperFilters(r,'platform');else if(rt==='/developer/audit/logs'||rt==='/developer/audit/details')initDeveloperFilters(r,'audit');else if(rt==='/developer/webhooks/create')initWebhook(r,'create');else if(rt==='/developer/webhooks/deliveries'||rt==='/developer/webhooks/details')initWebhook(r,'delivery');if(rt.startsWith('/developer/crud-generator'))initCrud(r);r.dataset.d2DeveloperReady='true'}
